"""Lesson gm12-u3-l37 (8A compound interest investments with regular additions) guided worksheet, CFAT / revision-booklet style (tools/deck/ws2.py). DRAFT.
Questions verbatim, same items and order as tools/deck/gm12-u3-l37/build.py (Do Now not on the worksheet; no CAS steps).
Sources (not printed): APK = Cambridge U1&2 Ch 3 skills checklist 3H #22 (illustrated with Cambridge U3&4 8A p. 393); VCAA 2017 Further Exam 2 Q5c (Edrolo U1&2 3E Q12).
Examples 1-5 = Cambridge U3&4 pp. 392-396. You trys = written YT-8A-1, YT-8A-2, Edrolo U3&4 6F WE1a, 6F WE1b, written YT-8A-5.
Exits = VCAA 2018 Exam 1 Q17, Q18 (Edrolo 6F Q16a-b), VCAA 2021 Exam 1 Q22 (6F Q17).
Output: lessons/8A worksheet(.html/.pdf) + solutions.   Run: python3 tools/deck/gm12-u3-l37/worksheet.py"""
import os, sys
H = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(H, '..'))
from ws2 import *
import ws2
A = lambda v: ans(v)
RR = lambda v0, rule, L='V': f'<i>{L}</i><sub>0</sub> = {v0}, &nbsp; <i>{L}</i><sub><i>n</i>+1</sub> = {rule}'
VN = '<i>V<sub>n</sub></i>'
FORM = 'Model this investment using a recurrence relation of the form ' + RR('the principal', '<i>RV<sub>n</sub></i> + <i>D</i>')
def axes(pts=(), col='#000'):
    W, Hh, l, b, t = 230, 120, 40, 18, 8
    X = lambda n: l + (W - l - 10) * n / 4.3; Y = lambda v: t + (Hh - b - t) * (1 - v / 500)
    o = [f'<line x1="{l}" y1="{Y(0)}" x2="{W-6}" y2="{Y(0)}" stroke="#000"/><line x1="{l}" y1="{t}" x2="{l}" y2="{Y(0)}" stroke="#000"/>']
    for v in range(100, 501, 100): o.append(f'<line x1="{l}" y1="{Y(v)}" x2="{W-6}" y2="{Y(v)}" stroke="#ccc" stroke-width=".6"/><text x="{l-3}" y="{Y(v)+3}" font-size="8" text-anchor="end">{v}</text>')
    for n in range(5): o.append(f'<text x="{X(n)}" y="{Y(0)+11}" font-size="8" text-anchor="middle">{n}</text>')
    o.append(f'<text x="{W-6}" y="{Y(0)+11}" font-size="8" font-style="italic">n</text><text x="{l+3}" y="{t+6}" font-size="8" font-style="italic">Vₙ</text>')
    o.append('<g class="ans">' + ''.join(f'<circle cx="{X(n)}" cy="{Y(v)}" r="2.6" fill="{col}"/>' for n, v in enumerate(pts)) + '</g>')
    return f'<svg viewBox="0 0 {W} {Hh}" style="width:62mm;display:block;margin:1mm auto">{"".join(o)}</svg>'

P = [title('8A', 'Compound interest investments with regular additions')]
LI = ['To be able to generate a sequence from a recurrence relation that combines both geometric and linear growth or decay.', 'To be able to model compound interest investments with additions to the principal.',
      'To be able to use a recurrence relation to analyse compound interest investments with additions to the principal.', 'To be able to determine the annual interest rate from a recurrence relation.']
P.append(lis(LI))
P.append(sect('Activating prior knowledge', 'Year 11 skill and a VCAA question'))
P.append(box('Question 1', q('Use a recurrence relation to model compound interest for investments or loans: $5000 invested at 4% per annum, compounding annually.') + space(16, 'R = 1 + 4/100 = 1.04; V₀ = 5000, Vₙ₊₁ = 1.04Vₙ'), ''))
P.append(box('Question 2 · VCAA 2017 Exam 2 Q5c', q('Alex is a mobile mechanic. He uses a van to travel to his customers to repair their cars. The value of Alex’s van is depreciated using the reducing balance method of depreciation. The value of the van, in dollars, after <i>n</i> years, <i>R<sub>n</sub></i>, can be modelled by the following recurrence relation.<br>' + RR('75 000', '0.943<i>R<sub>n</sub></i>', 'R') + '<br>At what annual percentage rate is the value of the van depreciated each year?') + space(14, '(1 − 0.943) × 100 = 5.7%'), ''))

P.append(sect('8A Combining geometric and linear growth', 'Example, then you try'))
P.append(exyt('Example 1 · Generating a sequence from a recurrence relation of the form Vₙ₊₁ = R × Vₙ ± D',
  q('Write down the first five terms of the sequence generated by the recurrence relation ' + RR('3', '4' + VN + ' − 1')) + q('Terms: ' + A('3, 11, 43, 171, 683')),
  'You try 1', q('Write down the first five terms of the sequence generated by the recurrence relation ' + RR('2', '3' + VN + ' + 1')) + space(24, '2, 7, 22, 67, 202')))
P.append(exyt('Example 2 · Modelling compound interest investments with additions to the principal (1)',
  q('Fred has saved $5000 and invests this in a compound interest account paying 4% per annum, compounding yearly. He also adds an extra $1000 each year. ' + FORM + ' where ' + VN + ' is the value of the investment after <i>n</i> years.')
  + q('<i>V</i><sub>0</sub> = ' + A('5000') + ' &nbsp; <i>D</i> = ' + A('1000') + ' &nbsp; <i>R</i> = ' + A('1.04')) + q('Recurrence relation: ' + A('V₀ = 5000, Vₙ₊₁ = 1.04Vₙ + 1000')),
  'You try 2', q('Maya has saved $4000 and invests this in a compound interest account paying 5% per annum, compounding yearly. She also adds an extra $800 each year. ' + FORM + ' where ' + VN + ' is the value of the investment after <i>n</i> years.') + space(24, 'R = 1.05; V₀ = 4000, Vₙ₊₁ = 1.05Vₙ + 800')))
P.append(exyt('Example 3 · Modelling compound interest investments with additions to the principal (2)',
  q('Nor invests $1200 and plans to add an extra $50 each month. The account pays interest at a rate of 3% per annum, compounding monthly. ' + FORM + ' where ' + VN + ' is the value of the investment after <i>n</i> months.')
  + q('<i>V</i><sub>0</sub> = ' + A('1200') + ' &nbsp; <i>D</i> = ' + A('50') + ' &nbsp; <i>R</i> = ' + A('1 + 3/1200 = 1.0025')) + q('Recurrence relation: ' + A('V₀ = 1200, Vₙ₊₁ = 1.0025Vₙ + 50')),
  'You try 3', q('An annuity investment currently has a balance of $3600 and earns interest at a rate of 3.6% per annum, compounding monthly. The investor adds an additional $500 into the account at the end of each month.')
  + parts([('a', 'Construct a recurrence relation that can be used to model the value of the investment, ' + VN + ', after <i>n</i> months.', 'R = 1 + 3.6/1200 = 1.003; V₀ = 3600, Vₙ₊₁ = 1.003 × Vₙ + 500', 22)])))

P.append(sect('8A Analysing annuity investments', 'Example, then you try'))
P.append(exyt('Example 4 · Using a recurrence relation to analyse compound interest investments with additions to the principal',
  q('Albert has an investment that can be modelled by the recurrence relation ' + RR('400', '1.005' + VN + ' + 30') + ' where ' + VN + ' is the value of the investment after <i>n</i> months.')
  + parts([('a', 'State the value of the initial investment. ' + A('$400'), '', 'L'),
           ('b', 'Determine the value of the investment after Albert has made three extra payments. Round your answer to the nearest cent.<br>' + A('V₁ = 432, V₂ = 464.16, V₃ = $496.48'), '', 'L'),
           ('c', 'What will be the value of his investment after 6 months? Round your answer to the nearest cent. ' + A('$594.42'), '', 'L'),
           ('d', 'Plot the points for the value of the investment after 0, 1, 2 and 3 months on a graph.' + axes([400, 432, 464.16, 496.48], '#c00000'), '', 2)]),
  'You try 4', q('(The investment in You try 3: ' + RR('3600', '1.003 × ' + VN + ' + 500') + ')')
  + parts([('b', 'How much will the account be worth after three months?', 'V₁ = 4110.80, V₂ = 4623.13, V₃ = $5137.00', 40)])))
P.append(exyt('Example 5 · Determining the annual interest rate from a recurrence relation',
  q('Determine the annual interest rates for each of the following investments.')
  + parts([('a', 'Consider an investment given by the recurrence relation ' + RR('400', '1.005<i>A<sub>n</sub></i> + 30', 'A') + ' where <i>A<sub>n</sub></i> is the value of the investment after <i>n</i> months.<br>' + A('1.005 = 1 + r/1200 → r = 6%'), '', 'L'),
           ('b', 'Consider an investment given by the recurrence relation ' + RR('2000', '1.012<i>W<sub>n</sub></i> + 500', 'W') + ' where <i>W<sub>n</sub></i> is the value of the investment after <i>n</i> quarters.<br>' + A('1.012 = 1 + r/400 → r = 4.8%'), '', 'L')]),
  'You try 5', q('Determine the annual interest rates for each of the following investments.')
  + parts([('a', 'Consider an investment given by the recurrence relation ' + RR('600', '1.004<i>A<sub>n</sub></i> + 40', 'A') + ' where <i>A<sub>n</sub></i> is the value of the investment after <i>n</i> months.', '0.4% × 12 = 4.8% per annum', 16),
           ('b', 'Consider an investment given by the recurrence relation ' + RR('3000', '1.015<i>W<sub>n</sub></i> + 200', 'W') + ' where <i>W<sub>n</sub></i> is the value of the investment after <i>n</i> quarters.', '1.5% × 4 = 6% per annum', 16)])))

P.append(sect('Exit tasks', 'Show what you know'))
EX = q('The value of an annuity investment, in dollars, after <i>n</i> years, ' + VN + ', can be modelled by the recurrence relation shown below.<br>' + RR('46 000', '1.0034 × ' + VN + ' + 500'))
P.append(box('Exit task 1 · VCAA 2018 Exam 1 Q17', EX + q('What is the value of the regular payment added to the principal of this annuity investment?')
  + mc(['$34.00', '$156.40', '$466.00', '$500.00', '$656.40'], 'D', cols=5) + why('D = 500, the amount added each year'), ''))
P.append(box('Exit task 2 · VCAA 2018 Exam 1 Q18', EX + q('Between the second and third years, the increase in the value of this investment is closest to')
  + mc(['$656', '$658', '$661', '$1315', '$1975'], 'C', cols=5) + why('V₂ = 47 315.03, V₃ = 47 975.90: increase 660.87'), ''))
P.append(box('Exit task 3 · VCAA 2021 Exam 1 Q22', q('Joanna deposited $12 000 in an investment account earning interest at the rate of 2.8% per annum, compounding monthly.<br>She would like this account to reach a balance of $25 000 after five years.<br>To achieve this balance, she will make an extra payment into the account each month, immediately after the interest is calculated.<br>The minimum value of this payment is closest to')
  + mc(['$113.85', '$174.11', '$580.16', '$603.22', '$615.47'], 'B', cols=5) + why('V₀ = 12 000, Vₙ₊₁ = (1 + 2.8/1200)Vₙ + D; V₆₀ = 25 000 gives D = 174.11'), ''))
SC = ['I can generate a sequence from a recurrence relation that combines both geometric and linear growth or decay.', 'I can model compound interest investments with additions to the principal.',
      'I can use a recurrence relation to analyse compound interest investments with additions to the principal.', 'I can determine the annual interest rate from a recurrence relation.']
P.append(close(SC, [('8A', 'Q1–14')], ['8A']))
build('l37', '8A', 'AoS 2 · Recursion and financial modelling', P)
R = os.path.join(ws2.ROOT, 'lessons')
for x, y in (('l37-worksheet', '8A worksheet'), ('l37-worksheet-solutions', '8A worksheet solutions')):
    for ext in ('.html', '.pdf'): os.replace(f'{R}/{x}{ext}', f'{R}/{y}{ext}')
